function GoldText({ children, size, style }) {
  return (
    <span style={{ position: 'relative', display: 'inline-block', fontSize: size, fontWeight: 900, letterSpacing: '-2px', lineHeight: 1, ...style }}>
      <span style={{ position: 'absolute', inset: 0, WebkitTextStroke: '14px #2A1A05', color: '#2A1A05', filter: 'drop-shadow(0 8px 10px rgba(0,0,0,.6))' }}>{children}</span>
      <span style={{ position: 'relative', background: 'linear-gradient(180deg,#FFF6C8 0%,#F5CE55 38%,#D9971F 62%,#FFE58A 100%)', WebkitBackgroundClip: 'text', backgroundClip: 'text', color: 'transparent' }}>{children}</span>
    </span>
  );
}

